89. // UnmarshalNebulaCertificate will unmarshal a protobuf byte representation of a nebula cert
90. func UnmarshalNebulaCertificate(b []byte) (*NebulaCertificate, error) {
91. 	if len(b) == 0 {
92. 		return nil, fmt.Errorf("nil byte array")
93. 	}
94. 	var rc RawNebulaCertificate
95. 	err := proto.Unmarshal(b, &rc)
96. 	if err != nil {
97. 		return nil, err
98. 	}
99. 
100. 	if rc.Details == nil {
101. 		return nil, fmt.Errorf("encoded Details was nil")
102. 	}
103. 
104. 	if len(rc.Details.Ips)%2 != 0 {
105. 		return nil, fmt.Errorf("encoded IPs should be in pairs, an odd number was found")
106. 	}
107. 
108. 	if len(rc.Details.Subnets)%2 != 0 {
109. 		return nil, fmt.Errorf("encoded Subnets should be in pairs, an odd number was found")
110. 	}
111. 
112. 	nc := NebulaCertificate{
113. 		Details: NebulaCertificateDetails{
114. 			Name:           rc.Details.Name,
115. 			Groups:         make([]string, len(rc.Details.Groups)),
116. 			Ips:            make([]*net.IPNet, len(rc.Details.Ips)/2),
117. 			Subnets:        make([]*net.IPNet, len(rc.Details.Subnets)/2),
118. 			NotBefore:      time.Unix(rc.Details.NotBefore, 0),
119. 			NotAfter:       time.Unix(rc.Details.NotAfter, 0),
120. 			PublicKey:      make([]byte, len(rc.Details.PublicKey)),
121. 			IsCA:           rc.Details.IsCA,
122. 			InvertedGroups: make(map[string]struct{}),
123. 			Curve:          rc.Details.Curve,
124. 		},
125. 		Signature: make([]byte, len(rc.Signature)),
126. 	}
127. 
128. 	copy(nc.Signature, rc.Signature)
129. 	copy(nc.Details.Groups, rc.Details.Groups)
130. 	nc.Details.Issuer = hex.EncodeToString(rc.Details.Issuer)
131. 
132. 	if len(rc.Details.PublicKey) < publicKeyLen {
133. 		return nil, fmt.Errorf("Public key was fewer than 32 bytes; %v", len(rc.Details.PublicKey))
134. 	}
135. 	copy(nc.Details.PublicKey, rc.Details.PublicKey)
136. 
137. 	for i, rawIp := range rc.Details.Ips {
138. 		if i%2 == 0 {
139. 			nc.Details.Ips[i/2] = &net.IPNet{IP: int2ip(rawIp)}
140. 		} else {
141. 			nc.Details.Ips[i/2].Mask = net.IPMask(int2ip(rawIp))
142. 		}
143. 	}
144. 
145. 	for i, rawIp := range rc.Details.Subnets {
146. 		if i%2 == 0 {
147. 			nc.Details.Subnets[i/2] = &net.IPNet{IP: int2ip(rawIp)}
148. 		} else {
149. 			nc.Details.Subnets[i/2].Mask = net.IPMask(int2ip(rawIp))
150. 		}
151. 	}
152. 
153. 	for _, g := range rc.Details.Groups {
154. 		nc.Details.InvertedGroups[g] = struct{}{}
155. 	}
156. 
157. 	return &nc, nil
158. }
