160. // UnmarshalNebulaCertificateFromPEM will unmarshal the first pem block in a byte array, returning any non consumed data
161. // or an error on failure
162. func UnmarshalNebulaCertificateFromPEM(b []byte) (*NebulaCertificate, []byte, error) {
163. 	p, r := pem.Decode(b)
164. 	if p == nil {
165. 		return nil, r, fmt.Errorf("input did not contain a valid PEM encoded block")
166. 	}
167. 	if p.Type == CertificateV2Banner {
168. 		return nil, r, fmt.Errorf("%w: %s", ErrInvalidPEMCertificateUnsupported, p.Type)
169. 	}
170. 	if p.Type != CertBanner {
171. 		return nil, r, fmt.Errorf("bytes did not contain a proper nebula certificate banner")
172. 	}
173. 	nc, err := UnmarshalNebulaCertificate(p.Bytes)
174. 	return nc, r, err
175. }
