177. func MarshalPrivateKey(curve Curve, b []byte) []byte {
178. 	switch curve {
179. 	case Curve_CURVE25519:
180. 		return pem.EncodeToMemory(&pem.Block{Type: X25519PrivateKeyBanner, Bytes: b})
181. 	case Curve_P256:
182. 		return pem.EncodeToMemory(&pem.Block{Type: P256PrivateKeyBanner, Bytes: b})
183. 	default:
184. 		return nil
185. 	}
186. }
187. 
188. func MarshalSigningPrivateKey(curve Curve, b []byte) []byte {
189. 	switch curve {
190. 	case Curve_CURVE25519:
191. 		return pem.EncodeToMemory(&pem.Block{Type: Ed25519PrivateKeyBanner, Bytes: b})
192. 	case Curve_P256:
193. 		return pem.EncodeToMemory(&pem.Block{Type: ECDSAP256PrivateKeyBanner, Bytes: b})
194. 	default:
195. 		return nil
196. 	}
197. }
