199. // MarshalX25519PrivateKey is a simple helper to PEM encode an X25519 private key
200. func MarshalX25519PrivateKey(b []byte) []byte {
201. 	return pem.EncodeToMemory(&pem.Block{Type: X25519PrivateKeyBanner, Bytes: b})
202. }
203. 
204. // MarshalEd25519PrivateKey is a simple helper to PEM encode an Ed25519 private key
205. func MarshalEd25519PrivateKey(key ed25519.PrivateKey) []byte {
206. 	return pem.EncodeToMemory(&pem.Block{Type: Ed25519PrivateKeyBanner, Bytes: key})
207. }
208. 
209. func UnmarshalPrivateKey(b []byte) ([]byte, []byte, Curve, error) {
210. 	k, r := pem.Decode(b)
211. 	if k == nil {
212. 		return nil, r, 0, fmt.Errorf("input did not contain a valid PEM encoded block")
213. 	}
214. 	var expectedLen int
215. 	var curve Curve
216. 	switch k.Type {
217. 	case X25519PrivateKeyBanner:
218. 		expectedLen = 32
219. 		curve = Curve_CURVE25519
220. 	case P256PrivateKeyBanner:
221. 		expectedLen = 32
222. 		curve = Curve_P256
223. 	default:
224. 		return nil, r, 0, fmt.Errorf("bytes did not contain a proper nebula private key banner")
225. 	}
226. 	if len(k.Bytes) != expectedLen {
227. 		return nil, r, 0, fmt.Errorf("key was not %d bytes, is invalid %s private key", expectedLen, curve)
228. 	}
229. 	return k.Bytes, r, curve, nil
230. }
231. 
232. func UnmarshalSigningPrivateKey(b []byte) ([]byte, []byte, Curve, error) {
233. 	k, r := pem.Decode(b)
234. 	if k == nil {
235. 		return nil, r, 0, fmt.Errorf("input did not contain a valid PEM encoded block")
236. 	}
237. 	var curve Curve
238. 	switch k.Type {
239. 	case EncryptedEd25519PrivateKeyBanner:
240. 		return nil, nil, Curve_CURVE25519, ErrPrivateKeyEncrypted
241. 	case EncryptedECDSAP256PrivateKeyBanner:
242. 		return nil, nil, Curve_P256, ErrPrivateKeyEncrypted
243. 	case Ed25519PrivateKeyBanner:
244. 		curve = Curve_CURVE25519
245. 		if len(k.Bytes) != ed25519.PrivateKeySize {
246. 			return nil, r, 0, fmt.Errorf("key was not %d bytes, is invalid Ed25519 private key", ed25519.PrivateKeySize)
247. 		}
248. 	case ECDSAP256PrivateKeyBanner:
249. 		curve = Curve_P256
250. 		if len(k.Bytes) != 32 {
251. 			return nil, r, 0, fmt.Errorf("key was not 32 bytes, is invalid ECDSA P256 private key")
252. 		}
253. 	default:
254. 		return nil, r, 0, fmt.Errorf("bytes did not contain a proper nebula Ed25519/ECDSA private key banner")
255. 	}
256. 	return k.Bytes, r, curve, nil
257. }
