312. func (p *Nebula) authorizeToken(token string, audiences []string) (*nebula.NebulaCertificate, *jwtPayload, error) {
313. 	jwt, err := jose.ParseSigned(token)
314. 	if err != nil {
315. 		return nil, nil, errs.UnauthorizedErr(err, errs.WithMessage("failed to parse token"))
316. 	}
317. 
318. 	// Extract Nebula certificate
319. 	h, ok := jwt.Headers[0].ExtraHeaders[NebulaCertHeader]
320. 	if !ok {
321. 		return nil, nil, errs.Unauthorized("failed to parse token: nebula header is missing")
322. 	}
323. 	s, ok := h.(string)
324. 	if !ok {
325. 		return nil, nil, errs.Unauthorized("failed to parse token: nebula header is not valid")
326. 	}
327. 	b, err := base64.StdEncoding.DecodeString(s)
328. 	if err != nil {
329. 		return nil, nil, errs.UnauthorizedErr(err, errs.WithMessage("failed to parse token: nebula header is not valid"))
330. 	}
331. 	c, err := nebula.UnmarshalNebulaCertificate(b)
332. 	if err != nil {
333. 		return nil, nil, errs.UnauthorizedErr(err, errs.WithMessage("failed to parse nebula certificate: nebula header is not valid"))
334. 	}
335. 
336. 	// Validate nebula certificate against CAs
337. 	if valid, err := c.Verify(now(), p.caPool); !valid {
338. 		if err != nil {
339. 			return nil, nil, errs.UnauthorizedErr(err, errs.WithMessage("token is not valid: failed to verify certificate against configured CA"))
340. 		}
341. 		return nil, nil, errs.Unauthorized("token is not valid: failed to verify certificate against configured CA")
342. 	}
343. 
344. 	var pub any
345. 	switch {
346. 	case c.Details.Curve == nebula.Curve_P256:
347. 		// When Nebula is used with ECDSA P-256 keys, both CAs and clients use the same type.
348. 		ecdhPub, err := ecdh.P256().NewPublicKey(c.Details.PublicKey)
349. 		if err != nil {
350. 			return nil, nil, errs.UnauthorizedErr(err, errs.WithMessage("failed to parse nebula public key"))
351. 		}
352. 		publicKeyBytes := ecdhPub.Bytes()
353. 		pub = &ecdsa.PublicKey{ // convert back to *ecdsa.PublicKey, because our jose package nor go-jose supports *ecdh.PublicKey
354. 			Curve: elliptic.P256(),
355. 			X:     big.NewInt(0).SetBytes(publicKeyBytes[1:33]),
356. 			Y:     big.NewInt(0).SetBytes(publicKeyBytes[33:]),
357. 		}
358. 	case c.Details.IsCA:
359. 		pub = ed25519.PublicKey(c.Details.PublicKey)
360. 	default:
361. 		pub = x25519.PublicKey(c.Details.PublicKey)
362. 	}
363. 
364. 	// Validate token with public key
365. 	var claims jwtPayload
366. 	if err := jose.Verify(jwt, pub, &claims); err != nil {
367. 		return nil, nil, errs.UnauthorizedErr(err, errs.WithMessage("token is not valid: signature does not match"))
368. 	}
369. 
370. 	// According to "rfc7519 JSON Web Token" acceptable skew should be no
371. 	// more than a few minutes.
372. 	if err = claims.ValidateWithLeeway(jose.Expected{
373. 		Issuer: p.Name,
374. 		Time:   now(),
375. 	}, time.Minute); err != nil {
376. 		return nil, nil, errs.UnauthorizedErr(err, errs.WithMessage("token is not valid: invalid claims"))
377. 	}
378. 
379. 	// Validate token and subject too.
380. 	if !matchesAudience(claims.Audience, audiences) {
381. 		return nil, nil, errs.Unauthorized("token is not valid: invalid claims")
382. 	}
383. 	if claims.Subject == "" {
384. 		return nil, nil, errs.Unauthorized("token is not valid: subject cannot be empty")
385. 	}
386. 
387. 	return c, &claims, nil
388. }
