390. type nebulaSANsValidator struct {
391. 	Name string
392. 	IPs  []*net.IPNet
393. }
394. 
395. // Valid verifies that the SANs stored in the validator are contained with those
396. // requested in the x509 certificate request.
397. func (v nebulaSANsValidator) Valid(req *x509.CertificateRequest) error {
398. 	dnsNames, ips, emails, uris := x509util.SplitSANs([]string{v.Name})
399. 	if len(req.DNSNames) > 0 {
400. 		if err := dnsNamesValidator(dnsNames).Valid(req); err != nil {
401. 			return err
402. 		}
403. 	}
404. 	if len(req.EmailAddresses) > 0 {
405. 		if err := emailAddressesValidator(emails).Valid(req); err != nil {
406. 			return err
407. 		}
408. 	}
409. 	if len(req.URIs) > 0 {
410. 		if err := newURIsValidator(context.Background(), uris).Valid(req); err != nil {
411. 			return err
412. 		}
413. 	}
414. 	if len(req.IPAddresses) > 0 {
415. 		for _, ip := range req.IPAddresses {
416. 			var valid bool
417. 			// Check ip in name
418. 			for _, ipInName := range ips {
419. 				if ip.Equal(ipInName) {
420. 					valid = true
421. 					break
422. 				}
423. 			}
424. 			// Check ip network
425. 			if !valid {
426. 				for _, ipNet := range v.IPs {
427. 					if ip.Equal(ipNet.IP) {
428. 						valid = true
429. 						break
430. 					}
431. 				}
432. 			}
433. 			if !valid {
434. 				for _, ipNet := range v.IPs {
435. 					ips = append(ips, ipNet.IP)
436. 				}
437. 				return errs.Forbidden("certificate request contains invalid IP addresses - got %v, want %v", req.IPAddresses, ips)
438. 			}
439. 		}
440. 	}
441. 
442. 	return nil
443. }
