445. type nebulaPrincipalsValidator struct {
446. 	Name string
447. 	IPs  []*net.IPNet
448. }
449. 
450. // Valid checks that the SignSSHOptions principals contains only names in the
451. // Nebula certificate.
452. func (v nebulaPrincipalsValidator) Valid(got SignSSHOptions) error {
453. 	for _, p := range got.Principals {
454. 		var valid bool
455. 		if p == v.Name {
456. 			valid = true
457. 		}
458. 		if !valid {
459. 			if ip := net.ParseIP(p); ip != nil {
460. 				for _, ipnet := range v.IPs {
461. 					if ip.Equal(ipnet.IP) {
462. 						valid = true
463. 						break
464. 					}
465. 				}
466. 			}
467. 		}
468. 
469. 		if !valid {
470. 			ips := make([]net.IP, len(v.IPs))
471. 			for i, ipNet := range v.IPs {
472. 				ips[i] = ipNet.IP
473. 			}
474. 			return errs.Forbidden(
475. 				"ssh certificate principals contains invalid name or IP addresses - got %v, want %s or %v",
476. 				got.Principals, v.Name, ips,
477. 			)
478. 		}
479. 	}
480. 	return nil
481. }
